<script lang="ts">
  import { onMount } from 'svelte';
  import { TeamService, InfrastructureService } from '../../bindings/github.com/blacknode/blacknode/internal/service';
  import type { Runbook, Job, JobSchedule, MonitorView } from '../../bindings/github.com/blacknode/blacknode/internal/service/models';
  import type { OperationDocument, OperationEvent } from '../../bindings/github.com/blacknode/blacknode/internal/store/models';
  import PageHeader from './PageHeader.svelte';
  import SettingsPanel from './SettingsPanel.svelte';
  import ConfirmDanger from './ConfirmDanger.svelte';
  import InfrastructureTerminal from './InfrastructureTerminal.svelte';
  import { Share2 } from '@lucide/svelte';
  type Member = {id:string;name:string;role:string;hostIDs:string[];expiresAt:number;revoked:boolean};
  type Host = {id:string;name:string;host:string;environment:string};
  type Session = {id:string;hostID:string;ownerID:string;title:string;members:Record<string,string>;startedAt:number;closed:boolean};
  type Trigger = {id:string;name:string;bookID:string;bookRevision:number;hostIDs:string[];expiresAt:number;enabled:boolean;cooldownSeconds:number;lastRunAt:number};
  let section = $state('overview'); let sharedConfig = $state(false);
  let endpoint = $state('http://127.0.0.1:9250'); let token = $state(''); let connected = $state(false);
  let me = $state<Member | null>(null);let hosts = $state<Host[]>([]);let monitors = $state<MonitorView[]>([]);let books = $state<Runbook[]>([]);let jobs = $state<Job[]>([]);let schedules = $state<(JobSchedule & {revision:number})[]>([]);let members = $state<Member[]>([]);let triggers = $state<Trigger[]>([]);let sessions = $state<Session[]>([]);let audit = $state<OperationEvent[]>([]);
  let error = $state('');let notice = $state('');let busy = $state(false);let seed = $state('');
  let bookID = $state('');let hostIDs = $state<string[]>([]);let variables = $state('{}');let scheduleName = $state('');let interval = $state(3600);
  let memberName = $state('');let role = $state('viewer');let grantHours = $state(8);let scope = $state<string[]>([]);let issued = $state('');
  let triggerName = $state('');let triggerDays = $state(7);let cooldown = $state(60);
  let sessionHost = $state('');let active = $state<Session | null>(null);let inviteID = $state('');let inviteMode = $state('observer');
  let trust = $state({host:'',port:22,keyType:'ssh-ed25519',presentedKey:'',fingerprint:''});
  let confirm = $state<{title:string;body:string;production:string[];run:()=>Promise<unknown>} | null>(null);
  let admin = $derived(me?.role === 'admin');let operator = $derived(admin || me?.role === 'operator');
  let chosenBook = $derived(books.find(b => b.id === bookID));
  let activeMode = $derived(active && me ? (admin ? 'peer' : active.members[me.id] ?? 'observer') : 'observer');
  const fmt = (v:number) => v ? new Date(v).toLocaleString() : '—';
  async function api<T>(method:string,path:string,body?:unknown):Promise<T>{return JSON.parse(await TeamService.Request(method,path,body === undefined ? '' : JSON.stringify(body)));}
  async function action(fn:()=>Promise<unknown>){busy = true;error = '';notice = '';try{await fn();}catch(e){error = String(e);}finally{busy = false;}}
  async function refresh(){
    me = await api<Member>('GET','/api/me');
    [hosts,monitors,books,jobs,sessions] = await Promise.all([api<Host[]>('GET','/api/hosts'),api<MonitorView[]>('GET','/api/monitors'),api<Runbook[]>('GET','/api/runbooks'),api<Job[]>('GET','/api/jobs'),api<Session[]>('GET','/api/sessions')]);
    const docs = await api<OperationDocument[]>('GET','/api/schedules');schedules = docs.map(d => ({...JSON.parse(d.body),revision:d.revision}));
    if(me.role === 'admin')[members,triggers,audit] = await Promise.all([api<Member[]>('GET','/api/members'),api<Trigger[]>('GET','/api/triggers'),api<OperationEvent[]>('GET','/api/audit')]);else {members = [];triggers = [];audit = [];}
    if(active)active = sessions.find(s => s.id === active?.id) ?? null;
    connected = true;
  }
  function review(title:string,body:string,run:()=>Promise<unknown>,ids:string[] = []){confirm = {title,body,run,production:hosts.filter(h => ids.includes(h.id) && h.environment === 'production').map(h => h.name)};}
  function requestJob(){if(!chosenBook)throw new Error('Select a runbook');if(!hostIDs.length)throw new Error('Select at least one host');const values = JSON.parse(variables);if(!values || Array.isArray(values) || typeof values !== 'object' || Object.values(values).some(v => typeof v !== 'string'))throw new Error('Variables must be a JSON object of string values');return {bookID,bookRevision:chosenBook.revision,hostIDs:[...hostIDs],values};}
  function reviewJob(kind:'job'|'schedule'|'trigger'){
    void action(async () => {const job = requestJob();const book = structuredClone($state.snapshot(chosenBook!));const title = kind === 'job' ? 'Run saved runbook' : kind === 'schedule' ? 'Create persistent schedule' : 'Create webhook trigger';
      const payload = kind === 'job' ? job : kind === 'schedule' ? {name:scheduleName,everySeconds:interval,job} : {name:triggerName,bookID:job.bookID,bookRevision:job.bookRevision,hostIDs:job.hostIDs,expiresAt:Date.now()+triggerDays*86400000,enabled:true,cooldownSeconds:cooldown};
      review(title,`${book.name}, revision ${book.revision}\nHosts: ${hosts.filter(h => job.hostIDs.includes(h.id)).map(h => h.name).join(', ')}\n${kind === 'schedule' ? `Interval: ${interval} seconds. Continues until deleted.\n` : ''}${kind === 'trigger' ? `Expires in ${triggerDays} days. Cooldown ${cooldown}s. Uses variable defaults; request bodies are ignored.\n` : ''}\n${JSON.stringify(book,null,2)}`,async () => {const response = await api<{token?:string;trigger?:Trigger}>('POST',`/api/${kind === 'job' ? 'jobs' : kind === 'schedule' ? 'schedules' : 'triggers'}`,payload);if(response.token)issued = `Webhook: ${endpoint.replace(/\/$/,'')}/hooks/${response.trigger?.id}\nAuthorization: Bearer ${response.token}`;await refresh();notice = `${title} completed`;},job.hostIDs);
    });
  }
  function openSession(){const id = sessionHost;review('Open shared SSH session',`Start an interactive shell on ${hosts.find(h => h.id === id)?.name}?`,async () => {active = await api<Session>('POST','/api/sessions',{hostID:id,cols:100,rows:28});await refresh();},[id]);}
  function issueMember(){const payload = {name:memberName,role,hostIDs:[...scope],expiresAt:Date.now()+grantHours*3600000};review('Issue team access',`${memberName}: ${role}, expires in ${grantHours} hours. ${role === 'admin' ? 'Administrator access covers all hosts and configuration.' : `Hosts: ${hosts.filter(h => scope.includes(h.id)).map(h => h.name).join(', ') || 'None'}`}`,async () => {const response = await api<{member:Member;token:string}>('POST','/api/members',payload);issued = `Member ID: ${response.member.id}\nAccess token: ${response.token}`;await refresh();});}
  function downloadSeed(){const url = URL.createObjectURL(new Blob([seed],{type:'application/json'}));const a = document.createElement('a');a.href = url;a.download = 'blacknode-runner-seed.json';a.click();setTimeout(() => URL.revokeObjectURL(url),1000);}
  onMount(() => {void action(async () => {const cfg = await TeamService.Connection();endpoint = cfg.url || endpoint;if(cfg.hasToken)await refresh();});});
</script>

{#if sharedConfig}<div class="flex h-full min-h-0 flex-col"><div class="ops-actions p-3"><button onclick={() => sharedConfig = false}>Back to runner</button></div><SettingsPanel initialSection="team" /></div>
{:else}
<div class="flex h-full min-h-0 flex-col"><PageHeader icon={Share2} title="Team operations" subtitle="Always-on runner, scoped access and shared sessions" /><div class="ops-body ops-form">
  {#if error}<p class="ops-error" role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
  <div class="ops-card ops-form"><div class="ops-grid"><label>Runner URL<input bind:value={endpoint} disabled={connected || busy} /></label>{#if !connected}<label>Access token<input type="password" bind:value={token} autocomplete="off" /></label>{/if}</div><div class="ops-actions">
    {#if connected}<span>{me?.name} · {me?.role} · expires {me?.expiresAt ? fmt(me.expiresAt) : 'when rotated'}</span><button disabled={busy} onclick={() => action(refresh)}>Refresh runner</button><button disabled={busy} onclick={() => action(async () => {active = null;await TeamService.Disconnect();connected = false;me = null;issued = '';})}>Disconnect runner</button>
    {:else}<button class="primary" disabled={busy || !token} onclick={() => action(async () => {await TeamService.SaveConnection(endpoint,token);token = '';await refresh();})}>Connect runner</button>{/if}<button onclick={() => sharedConfig = true}>Shared configuration</button></div>
    {#if !connected}<p class="ops-muted">Start blacknode-runner with its own database, vault password and bootstrap token. Use HTTPS, or HTTP on loopback. Tokens are encrypted in your desktop vault.</p>{/if}
  </div>
  {#if connected}
  <nav class="ops-actions" aria-label="Team sections">{#each ['overview','runbooks','sessions',...(admin ? ['members','triggers','audit','configuration'] : [])] as item}<button class:primary={section === item} onclick={() => section = item}>{item.charAt(0).toUpperCase()+item.slice(1)}</button>{/each}</nav>
  {#if issued}<div class="ops-card ops-form"><p>Copy this credential now. It is only displayed once; share it through a secure channel.</p><pre class="ops-code">{issued}</pre><button onclick={() => issued = ''}>Dismiss credential</button></div>{/if}
  {#if section === 'overview'}
    <div class="ops-grid"><div class="ops-card"><h3>Scoped hosts · {hosts.length}</h3>{#each hosts as h (h.id)}<p>{h.name} · {h.host} · {h.environment || 'unclassified'}</p>{:else}<p>No hosts in your scope.</p>{/each}</div><div class="ops-card"><h3>Runner monitors · {monitors.length}</h3>{#each monitors as m (m.monitor.id)}<p>{m.monitor.name} · {m.state.samples.at(-1)?.status ?? 'pending'}</p>{:else}<p>No monitors in your scope.</p>{/each}</div></div>
    <p class="ops-muted">Jobs, schedules and monitoring continue while the desktop is closed. Sessions end when their owner's grant expires, or after eight hours.</p>
  {:else if section === 'runbooks' || section === 'triggers'}
    {#if operator}<div class="ops-card ops-form"><label>Runner runbook<select bind:value={bookID}><option value="">Select a saved runbook</option>{#each books as b (b.id)}<option value={b.id}>{b.name} · revision {b.revision}</option>{/each}</select></label><fieldset><legend>Target hosts</legend><div class="ops-actions">{#each hosts as h (h.id)}<label><input type="checkbox" bind:group={hostIDs} value={h.id} /> {h.name}{h.environment === 'production' ? ' · production' : ''}</label>{/each}</div></fieldset>
      {#if chosenBook}<details><summary>Saved definition</summary><pre class="ops-code">{JSON.stringify(chosenBook,null,2)}</pre></details>{/if}
      {#if section === 'runbooks'}<label>Variables (JSON string values)<textarea bind:value={variables} rows="3" spellcheck="false"></textarea></label><button class="primary" disabled={busy || !chosenBook || !hostIDs.length} onclick={() => reviewJob('job')}>Review runbook execution</button>
        {#if admin}<div class="ops-grid"><label>Schedule name<input bind:value={scheduleName} /></label><label>Interval in seconds<input type="number" min="60" max="31536000" bind:value={interval} /></label></div><button disabled={busy || !chosenBook || !hostIDs.length || !scheduleName} onclick={() => reviewJob('schedule')}>Review persistent schedule</button>{/if}
      {:else}<div class="ops-grid"><label>Trigger name<input bind:value={triggerName} /></label><label>Expires in days<input type="number" min="1" max="365" bind:value={triggerDays} /></label><label>Cooldown in seconds<input type="number" min="60" bind:value={cooldown} /></label></div><button disabled={busy || !chosenBook || !hostIDs.length || !triggerName} onclick={() => reviewJob('trigger')}>Review webhook trigger</button>{/if}
    </div>{/if}
    {#if section === 'runbooks'}
      <h3>Jobs</h3>{#each jobs as job (job.id)}<div class="ops-card ops-form"><div class="ops-actions"><span>{job.book.name} · {job.status}</span>{#if operator && (job.status === 'running' || job.status === 'queued')}<button disabled={busy} onclick={() => review('Cancel job',`Cancel ${job.book.name}?`,async () => {await api('DELETE',`/api/jobs/${job.id}`);await refresh();})}>Cancel</button>{/if}</div><details><summary>Results</summary><pre class="ops-code">{JSON.stringify(job,null,2)}</pre></details></div>{:else}<p>No jobs yet.</p>{/each}
      <h3>Schedules</h3>{#each schedules as s (s.id)}<div class="ops-card ops-actions"><span>{s.name} · {s.enabled ? 'enabled' : 'paused'} · next {fmt(s.nextRunAt)} {s.lastError}</span>{#if admin}<button disabled={busy} onclick={() => review('Delete schedule',`Stop future runs of ${s.name}?`,async () => {await api('DELETE',`/api/schedules/${s.id}?revision=${s.revision}`);await refresh();})}>Delete</button>{/if}</div>{:else}<p>No schedules yet.</p>{/each}
    {:else}{#each triggers as t (t.id)}<div class="ops-card ops-form"><p>{t.name} · {t.enabled ? 'enabled' : 'disabled'} · expires {fmt(t.expiresAt)} · revision {t.bookRevision}</p><code>{endpoint.replace(/\/$/,'')}/hooks/{t.id}</code><p>Last run: {fmt(t.lastRunAt)} · cooldown {t.cooldownSeconds}s</p>{#if t.enabled}<button disabled={busy} onclick={() => review('Disable webhook',`Disable ${t.name}?`,async () => {await api('DELETE',`/api/triggers/${t.id}`);await refresh();})}>Disable trigger</button>{/if}</div>{:else}<p>No triggers yet.</p>{/each}{/if}
  {:else if section === 'sessions'}
    {#if operator}<div class="ops-actions"><label>SSH host<select bind:value={sessionHost}><option value="">Select host</option>{#each hosts as h (h.id)}<option value={h.id}>{h.name}</option>{/each}</select></label><button disabled={busy || !sessionHost} onclick={openSession}>Open shared session</button></div>{/if}
    {#each sessions as s (s.id)}<div class="ops-card ops-actions"><span>{s.title} · {s.closed ? 'ended' : 'live'} · {s.members[me!.id] || 'administrator'}</span><button onclick={() => active = s}>Join {s.closed ? 'output' : 'session'}</button>{#if !s.closed && (admin || s.ownerID === me?.id)}<button disabled={busy} onclick={() => review('Close shared session',`Close ${s.title} for everyone?`,async () => {await api('DELETE',`/api/sessions/${s.id}`);if(active?.id === s.id)active = null;await refresh();})}>Close session</button>{/if}</div>{:else}<p>No shared sessions available.</p>{/each}
    {#if active}{@const a = active}<div class="ops-actions"><h3>{a.title} · {activeMode}</h3><button onclick={() => active = null}>Leave view</button></div>
      {#key `${a.id}:${activeMode}`}<InfrastructureTerminal sessionID={a.id} readonly={activeMode !== 'peer' || a.closed} connect={async () => {}} read={after => api('GET',`/api/sessions/${a.id}/output?after=${after}`)} write={data => api('POST',`/api/sessions/${a.id}/input`,{data})} resize={(cols,rows) => api('POST',`/api/sessions/${a.id}/input`,{cols,rows})} />{/key}
      <p class="ops-muted">Leaving this view keeps the session running. Owners and administrators can close it for everyone.</p>
      {#if !a.closed && (admin || a.ownerID === me?.id)}<div class="ops-grid"><label>Member ID<input bind:value={inviteID} list="team-member-ids" /><datalist id="team-member-ids">{#each members.filter(m => !m.revoked) as m}<option value={m.id}>{m.name}</option>{/each}</datalist></label><label>Access<select bind:value={inviteMode}><option value="observer">Observer (read only)</option><option value="peer">Peer (can type)</option><option value="remove">Remove access</option></select></label></div><button disabled={busy || !inviteID} onclick={() => action(async () => {await api('POST',`/api/sessions/${a.id}/members`,{memberID:inviteID,mode:inviteMode});await refresh();})}>Update invitation</button><pre class="ops-code">{JSON.stringify(a.members,null,2)}</pre>{/if}
    {/if}
  {:else if section === 'members' && admin}
    <div class="ops-card ops-form"><div class="ops-grid"><label>Name<input bind:value={memberName} /></label><label>Role<select bind:value={role}><option value="viewer">Viewer</option><option value="operator">Operator</option><option value="admin">Administrator</option></select></label><label>Expires in hours<input type="number" min="1" max="720" bind:value={grantHours} /></label></div><p class="ops-muted">Viewers inspect and observe. Operators run saved runbooks and share sessions. Administrators manage access, schedules, triggers and configuration.</p>{#if role !== 'admin'}<fieldset><legend>Allowed hosts</legend><div class="ops-actions">{#each hosts as h (h.id)}<label><input type="checkbox" bind:group={scope} value={h.id} /> {h.name}</label>{/each}</div></fieldset>{/if}<button disabled={busy || !memberName} onclick={issueMember}>Review access grant</button></div>
    {#each members as m (m.id)}<div class="ops-card ops-form"><p>{m.name} · {m.role} · {m.revoked ? 'revoked' : m.expiresAt ? `expires ${fmt(m.expiresAt)}` : 'bootstrap'}</p><code>{m.id}</code>{#if !m.revoked && m.id !== me?.id && m.id !== 'bootstrap'}<button disabled={busy} onclick={() => review('Revoke access',`Revoke ${m.name}'s access and end sessions they own?`,async () => {await api('DELETE',`/api/members/${m.id}`);await refresh();})}>Revoke</button>{/if}</div>{/each}
  {:else if section === 'audit' && admin}<div class="overflow-auto"><table class="ops-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Detail</th></tr></thead><tbody>{#each audit as event (event.seq)}<tr><td>{fmt(event.at)}</td><td>{event.title}</td><td>{event.kind}</td><td><pre class="whitespace-pre-wrap break-all">{event.body}</pre></td></tr>{/each}</tbody></table></div>
  {:else if section === 'configuration' && admin}
    <div class="ops-card ops-form"><h3>Seed runner configuration</h3><p class="ops-muted">Export SSH hosts, runbooks and monitors. Credentials and environment variables are excluded; the runner uses its SSH agent. Review commands for embedded secrets before sharing. Existing IDs are preserved on import.</p><div class="ops-actions"><button disabled={busy} onclick={() => action(async () => seed = await InfrastructureService.ExportRunnerSeed())}>Prepare desktop seed</button><button disabled={!seed} onclick={downloadSeed}>Download seed</button></div><label>Seed JSON<textarea rows="12" bind:value={seed} spellcheck="false"></textarea></label><button disabled={busy || !seed} onclick={() => action(async () => {const payload = JSON.parse(seed);review('Import runner configuration',`Add ${payload.hosts?.length ?? 0} hosts, ${payload.runbooks?.length ?? 0} runbooks and ${payload.monitors?.length ?? 0} monitors? Enabled monitors start polling immediately.`,async () => {await api('POST','/api/seed',payload);await refresh();notice = 'Configuration imported';});})}>Review import</button></div>
    <div class="ops-card ops-form"><h3>Trust an SSH host key</h3><p class="ops-muted">Verify the fingerprint through a trusted channel before approval.</p><div class="ops-grid"><label>Host<input bind:value={trust.host} /></label><label>Port<input type="number" min="1" max="65535" bind:value={trust.port} /></label><label>Key type<input bind:value={trust.keyType} /></label><label>Base64 public key<input bind:value={trust.presentedKey} /></label><label>SHA256 fingerprint<input bind:value={trust.fingerprint} /></label></div><button disabled={busy || !trust.presentedKey || !trust.fingerprint} onclick={() => {const payload = {...trust};review('Trust runner host key',`${payload.host}:${payload.port}\n${payload.keyType}\n${payload.fingerprint}`,async () => {await api('POST','/api/trust',payload);notice = 'Host key trusted';});}}>Review host key</button></div>
  {/if}
  {/if}
</div></div>
{/if}
{#if confirm}{@const c = confirm}<ConfirmDanger title={c.title} body={c.body} severity="warn" productionHosts={c.production} requirePhrase={c.production.length ? 'RUN IN PRODUCTION' : undefined} onCancel={() => confirm = null} onConfirm={async () => {await c.run();confirm = null;}} />{/if}
